parameters.functionCode:
const projectId = $json.projectId;
const projectName = $json.projectName;
const sessionState = $json.sessionState;
const triggeredBy = $json.triggeredBy || 'business-analyst';

// Generate app-container name (lowercase, no spaces)
const appContainerName = projectName.toLowerCase().replace(/\s+/g, '-');

return {
  json: {
    projectId,
    projectName,
    appContainerName,
    githubRepo: sessionState.githubRepo,
    targetBranch: sessionState.targetBranch || 'main',
    projectType: sessionState.projectType,
    platforms: sessionState.platforms || [],
    triggeredBy,
    startTime: new Date().toISOString()
  }
};

// Get Istio ingress gateway URL
// This would normally come from environment or config
const istioGateway = process.env.ISTIO_GATEWAY_URL || 'http://istio-ingressgateway.istio-system.svc.cluster.local';
const slackApiPath = '/slack/command';

// Get data from Extract Project Info (PostgreSQL only returns insert ID)
const extractData = $('Extract Project Info').first().json;
const appContainerName = extractData.appContainerName;
const githubRepo = extractData.githubRepo;
const projectId = extractData.projectId;

// Extract org and repo from GitHub URL
const repoMatch = githubRepo.match(/github\.com[/:]([^/]+)\/([^/.]+)/);
const githubOrg = repoMatch ? repoMatch[1] : 'shlapolosa';
const githubRepoName = repoMatch ? repoMatch[2] : appContainerName;

// Format Slack command payload for app-container creation
const slackCommand = `/create-app app-container=${appContainerName} github-org=${githubOrg} github-repo=${githubRepoName}`;

return {
  json: {
    slackApiUrl: `${istioGateway}${slackApiPath}`,
    slackCommand,
    appContainerName,
    githubOrg,
    githubRepoName,
    projectId
  }
};

// Parse Slack API response
const response = $json;
const prepareData = $('Prepare Slack API Call').first().json;
const appContainerName = prepareData.appContainerName;
const projectId = prepareData.projectId;

// Check if creation was successful
let creationSuccess = false;
let workflowName = null;
let message = '';

// Handle error from HTTP request
if ($json.error) {
  message = $json.error;
  creationSuccess = false;
} else if (response && response.text) {
  message = response.text;
  // Look for workflow creation confirmation
  if (message.includes('Workflow') || message.includes('created')) {
    creationSuccess = true;
    // Extract workflow name if present
    const workflowMatch = message.match(/Workflow:\s*([\w-]+)/);
    if (workflowMatch) {
      workflowName = workflowMatch[1];
    } else {
      // Assume standard workflow name pattern
      workflowName = `microservice-standard-contract-${appContainerName}`;
    }
  }
}

return {
  json: {
    projectId,
    appContainerName,
    creationSuccess,
    workflowName,
    message,
    monitoringRequired: creationSuccess
  }
};

const status = $json.stdout ? $json.stdout.trim() : '';
const parseData = $('Parse Response').first().json;
const workflowName = parseData.workflowName;
const projectId = parseData.projectId;

const isComplete = status === 'Succeeded';
const hasFailed = status === 'Failed' || status === 'Error';

return {
  json: {
    projectId,
    workflowName,
    status,
    isComplete,
    hasFailed,
    shouldRetry: !isComplete && !hasFailed
  }
};

const githubRepoUrl = $json.github_repo_url;
const checkStatusData = $('Check Status').first().json;
const projectId = checkStatusData.projectId;

// Extract org and repo from URL
const repoMatch = githubRepoUrl.match(/github\.com[/:]([^/]+)\/([^/.]+)/);
const githubOrg = repoMatch ? repoMatch[1] : 'shlapolosa';
const githubRepo = repoMatch ? repoMatch[2] : 'default-repo';

// Get GitHub token from environment
const githubToken = process.env.GITHUB_TOKEN || '';

return {
  json: {
    projectId,
    githubOrg,
    githubRepo,
    githubToken,
    githubRepoUrl,
    docsPath: 'docs/analysis'
  }
};

