const githubSetupData = $('Prepare GitHub Setup').first().json;
const projectId = githubSetupData.projectId;
const githubOrg = githubSetupData.githubOrg;
const githubRepo = githubSetupData.githubRepo;

const parseData = $('Parse Response').first().json;
const workflowName = parseData.workflowName;

const docsUrl = `https://github.com/${githubOrg}/${githubRepo}/tree/main/docs/analysis`;

// Create analysis report
const analysis = `# DevOps Infrastructure Setup\n\n` +
  `**Date**: ${new Date().toISOString()}\n` +
  `**Engineer**: DevOps Automation\n\n` +
  `## Infrastructure Created\n\n` +
  `- **Application Container**: Created via Argo Workflows\n` +
  `- **Workflow**: ${workflowName}\n` +
  `- **Status**: Succeeded\n` +
  `- **GitHub Repository**: ${githubOrg}/${githubRepo}\n` +
  `- **Documentation Folder**: docs/analysis\n\n` +
  `## Next Steps\n\n` +
  `1. Expert consultations will write their analysis to this folder\n` +
  `2. PRD will be generated and saved here\n` +
  `3. OAM definitions will be committed to this repository\n\n` +
  `All expert analysis documents will be available at: [${docsUrl}](${docsUrl})\n`;

return {
  json: {
    projectId,
    analysis,
    docsUrl,
    githubOrg,
    githubRepo,
    infrastructureReady: true
  }
};

